        metric_names = request.GET.getlist("metric") or None
        projects = self.get_projects(request, organization)
        try:
            tags = get_tags(
                projects,
                metric_names,
                use_case_id=get_use_case_id(request.GET.get("useCase", "release-health")),
            )
