                "uuid": app.uuid,
                "slug": app.slug,
                "name": app.name,
                "installs": app.installations__count,
                "avatars": serialize(avatars_to_app_map[app.id], request.user),
            }
            for app in sentry_apps
        ]

        return Response(apps)
