        if missing_counts:
            counts.update(
                dict(
                    ProcessingIssue.objects.with_num_events()
                    .filter(pk__in=list(missing_counts))
                    .values_list("id", "num_events")
                )
            )

        result = {}
        for item in item_list:
            result[item] = {"num_events": counts.get(item.id) or 0}

        return result

